/**
 * 100 soal Situational Judgment Test (SJT) INTEGRITAS untuk rekrutmen HR.
 * Konstruk: judgment & ethical decision-making di tempat kerja (McDaniel et al., SJT literature).
 * Return: array of ['text','options','answer','explanation']
 */

$rotate = static function (array $options, int $seed): array {
    $shift = abs($seed) % max(1, count($options));
    return array_merge(array_slice($options, $shift), array_slice($options, 0, $shift));
};

$make = static function (string $situation, string $correct, array $wrong, string $explanation, int $seed) use ($rotate): array {
    $options = $rotate(array_merge([$correct], array_slice($wrong, 0, 3)), $seed);
    return [
        'text' => 'Situasi: ' . $situation . ' Tindakan yang paling tepat adalah',
        'options' => $options,
        'answer' => array_search($correct, $options, true),
        'explanation' => $explanation,
    ];
};

