$questions = [];
$index = 0;

foreach ($scenarios as $scenario) {
    [$situation, $correct, $wrong, $explanation] = $scenario;
    $unit = $units[$index % count($units)];
    $context = 'Pada ' . $unit . ', ' . lcfirst($situation);
    $questions[] = $make($context, $correct, $wrong, $explanation, $index + 1);
    $index++;
}

// Tambah variasi hingga 100 jika skenario dasar kurang (safety net)
while (count($questions) < 100) {
    $base = $scenarios[count($questions) % count($scenarios)];
    [$situation, $correct, $wrong, $explanation] = $base;
    $unit = $units[count($questions) % count($units)];
    $variant = 'Dalam konteks audit mutu di ' . $unit . ', ' . lcfirst($situation);
    $questions[] = $make($variant, $correct, $wrong, $explanation, count($questions) + 100);
}

return array_slice($questions, 0, 100);
